use futures::FutureExt;
use sqlx::{postgres::PgPoolOptions, PgPool};
use tower::ServiceBuilder;

use super::{
    service::{PostgresRetryLogic, PostgresService},
    sink::PostgresSink,
};
use crate::sinks::{prelude::*, util::RealtimeSizeBasedDefaultBatchSettings};

const fn default_pool_size() -> u32 {
    5
}

/// Configuration for the `postgres` sink.
#[configurable_component(sink("postgres", "Deliver log data to a PostgreSQL database."))]
#[derive(Clone, Debug, Default)]
#[serde(deny_unknown_fields)]
pub struct PostgresConfig {
    /// The PostgreSQL server connection string.
    ///
    /// This can optionally contain the username and password used to
    /// authenticate with the server.
    #[configurable(metadata(
        docs::examples = "postgres://user:password@localhost/default"
    ))]
    pub endpoint: String,

    /// The table that data is inserted into.
    #[configurable(metadata(docs::examples = "table"))]
    pub table: String,

    /// The maximum size of the PostgreSQL connection pool.
    #[serde(default = "default_pool_size")]
    #[configurable(metadata(docs::examples = 5))]
    pub pool_size: u32,

    #[configurable(derived)]
    #[serde(default)]
    pub batch: BatchConfig<RealtimeSizeBasedDefaultBatchSettings>,

    #[configurable(derived)]
    #[serde(default)]
    pub request: TowerRequestConfig,

    #[configurable(derived)]
    #[serde(
        default,
        deserialize_with = "crate::serde::bool_or_struct",
        skip_serializing_if = "crate::serde::is_default"
    )]
    pub acknowledgements: AcknowledgementsConfig,
}

impl GenerateConfig for PostgresConfig {
    fn generate_config() -> toml::Value {
        toml::from_str(
            r#"endpoint = "postgres://user:password@localhost/default"
table = "table""#,
        )
        .unwrap()
    }
}

#[async_trait::async_trait]
#[typetag::serde(name = "postgres")]
impl SinkConfig for PostgresConfig {
    async fn build(&self, _cx: SinkContext) -> crate::Result<(VectorSink, Healthcheck)> {
        let connection_pool = PgPoolOptions::new()
            .max_connections(self.pool_size)
            .connect(&self.endpoint)
            .await?;

        let healthcheck = healthcheck(connection_pool.clone()).boxed();

        let batch_settings = self.batch.into_batcher_settings()?;
        let request_settings = self.request.into_settings();

        let service = PostgresService::new(
            connection_pool,
            self.table.clone(),
            self.endpoint.clone(),
        );
        let service = ServiceBuilder::new()
            .settings(request_settings, PostgresRetryLogic)
            .service(service);

        let sink = PostgresSink::new(service, batch_settings);

        Ok((VectorSink::from_event_streamsink(sink), healthcheck))
    }

    fn input(&self) -> Input {
        Input::new(DataType::Metric | DataType::Log | DataType::Trace)
    }

    fn acknowledgements(&self) -> &AcknowledgementsConfig {
        &self.acknowledgements
    }
}

async fn healthcheck(connection_pool: PgPool) -> crate::Result<()> {
    sqlx::query("SELECT 1").execute(&connection_pool).await?;
    Ok(())
}

